  {{ 'Gesamtsumme:' | Truncate: 61 | Align: 61}}{{ Tabulator }}{{ Report.TotalGrossPrice | Nummer : 'C', Report.CultureInfo | Truncate: 15 | Align: 15 }}
  {% unless Report.CurrencyISO == Report.ShipFromCountryCurrencyISO -%}
{% capture price %}({{ Report.TotalGrossPrice | DivideBy: Report.CurrencyFactor | Times: Report.ShipFromCountryCurrencyFactor | Nummer : 'C', Report.CultureInfo }}){% endcapture -%}
  {{ ' ' | Truncate: 61 | Align: 61 }}{{Tabulator}}{{ price | Truncate: 15 | Align: 15 }}
{% endunless -%}
